// Reads last processed update_id so we never re-handle old messages.
// NOTE: static data persists only while the workflow is ACTIVE (production runs).
const s = $getWorkflowStaticData('global');
const offset = s.lastUpdateId ? s.lastUpdateId + 1 : 0;
return [{ json: { offset, botToken: 'PASTE_YOUR_BOT_TOKEN_HERE' } }];

// Advance offset past everything received; emit one item per VOICE message.
// message_id (either voice notes OR forwarded audio files) is kept so the
// confirmation reply can reference/tag the original message.
const s = $getWorkflowStaticData('global');
const updates = $input.first().json.result ?? [];
if (updates.length) {
  s.lastUpdateId = Math.max(...updates.map(u => u.update_id));
}
const out = [];
for (const u of updates) {
  const m = u.message;
  // Treat a native voice note and a forwarded/uploaded audio file the same way
  const media = m?.voice ?? m?.audio;
  if (media) {
    out.push({
      json: {
        file_id: media.file_id,
        chat_id: m.chat.id,
        message_id: m.message_id,
        is_forwarded: Boolean(m.forward_date || m.forward_origin),
        technicien: m.from?.first_name ?? String(m.from?.id),
      },
    });
  }
}
return out;
